WITH flagged AS (SELECT *, CASE WHEN txn_time - LAG(txn_time) OVER (PARTITION BY txn_type ORDER BY txn_time, id) > INTERVAL 7 DAYS THEN 1 ELSE 0 END AS is_new_session FROM transactions), islands AS (SELECT *, SUM(is_new_session) OVER (PARTITION BY txn_type ORDER BY txn_time, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS burst_id FROM flagged) SELECT s.id, s.account_id, s.txn_type, s.amount, s.txn_time, s.merchant, s.is_flagged, s.is_new_session, (SELECT MAX(t2.amount) FROM transactions t2 WHERE t2.account_id = s.account_id) AS max_transaction_amount FROM islands s ORDER BY txn_time DESC
